def evaluate(text):
    """Evaluate an integer arithmetic expression."""
    if not isinstance(text, str):
        raise ValueError("expression must be a string")

    pos = 0
    length = len(text)

    def skip_space():
        nonlocal pos
        while pos < length and text[pos] in " \t":
            pos += 1

    def advance(count=1):
        nonlocal pos
        pos += count

    def parse_expression():
        value = parse_term()
        while True:
            skip_space()
            if pos < length and text[pos] in "+-":
                operator = text[pos]
                advance()
                right = parse_term()
                value = value + right if operator == "+" else value - right
            else:
                return value

    def parse_term():
        value = parse_unary()
        while True:
            skip_space()
            if text.startswith("//", pos):
                advance(2)
                right = parse_unary()
                value //= right
            elif pos < length and text[pos] in "*%":
                operator = text[pos]
                advance()
                right = parse_unary()
                if operator == "*":
                    value *= right
                else:
                    value %= right
            else:
                return value

    def parse_unary():
        skip_space()
        if pos < length and text[pos] in "+-":
            operator = text[pos]
            advance()
            value = parse_unary()
            return value if operator == "+" else -value
        return parse_power()

    def parse_power():
        value = parse_atom()
        skip_space()
        if text.startswith("**", pos):
            advance(2)
            exponent = parse_unary()
            if exponent < 0:
                raise ValueError("negative exponent")
            value = value ** exponent
        return value

    def parse_atom():
        nonlocal pos
        skip_space()
        if pos >= length:
            raise ValueError("missing operand")
        if text[pos] == "(":
            advance()
            value = parse_expression()
            skip_space()
            if pos >= length or text[pos] != ")":
                raise ValueError("unbalanced parentheses")
            advance()
            return value
        if not text[pos].isdigit():
            raise ValueError("invalid character")
        start = pos
        while pos < length and text[pos].isdigit():
            pos += 1
        digits = text[start:pos]
        if len(digits) > 1 and digits[0] == "0":
            raise ValueError("leading zero")
        return int(digits)

    result = parse_expression()
    skip_space()
    if pos != length:
        raise ValueError("unexpected input")
    return result
